package com.bank.topn.engine;

import com.bank.topn.model.Trade;
import java.util.*;
import java.util.logging.Logger;
import java.util.stream.Collectors;

// Stateful: keyed per-symbol volume inside a tumbling window; top-N at window close.
public class TopSymbolsProcessor {
    private static final Logger log = Logger.getLogger(TopSymbolsProcessor.class.getName());
    private final long windowSizeSec;
    private final int topN;

    // Keyed state: symbol → volume within the CURRENT window.
    private Map<String, Long> windowVolumes = new HashMap<>();
    private long currentWindowStart = -1;

    public TopSymbolsProcessor(long windowSizeSec, int topN) {
        this.windowSizeSec = windowSizeSec;
        this.topN = topN;
    }

    public void process(Trade t) {
        long windowStart = (t.getEventTimeSec() / windowSizeSec) * windowSizeSec;
        if (currentWindowStart == -1) currentWindowStart = windowStart;

        // Event-time crossed into a new window → close and emit the previous one.
        if (windowStart > currentWindowStart) {
            emitTopN(currentWindowStart);
            windowVolumes = new HashMap<>();   // reset keyed state for next window
            currentWindowStart = windowStart;
        }

        // Update keyed state: accumulate this symbol's volume.
        windowVolumes.merge(t.getSymbol(), t.getVolume(), Long::sum);
    }

    private void emitTopN(long windowStart) {
        List<Map.Entry<String, Long>> ranked = windowVolumes.entrySet().stream()
            .sorted(Map.Entry.<String, Long>comparingByValue().reversed())
            .limit(topN)
            .collect(Collectors.toList());
        log.info("=== TOP " + topN + " SYMBOLS BY VOLUME for window starting " + windowStart + "s ===");
        int rank = 1;
        for (Map.Entry<String, Long> e : ranked) {
            log.info("  #" + (rank++) + " " + e.getKey() + " volume=" + e.getValue());
        }
    }

    // Flush the final open window at end of stream.
    public void flush() { if (currentWindowStart != -1) emitTopN(currentWindowStart); }

    // CHECKPOINT: snapshot keyed state for exactly-once recovery.
    public Map<String, Long> checkpoint() {
        log.info("CHECKPOINT: snapshotting window state (" + windowVolumes.size() + " symbols)");
        return new HashMap<>(windowVolumes);
    }
}
