package com.bank.topn;

import com.bank.topn.engine.TopSymbolsProcessor;
import com.bank.topn.model.Trade;
import java.util.List;
import java.util.logging.Logger;

public class TopSymbolsDemo {
    private static final Logger log = Logger.getLogger(TopSymbolsDemo.class.getName());

    public static void main(String[] args) {
        // 60s tumbling windows, top 5. Trades span two minutes (0-59s, 60-119s).
        TopSymbolsProcessor proc = new TopSymbolsProcessor(60, 5);

        List<Trade> stream = List.of(
            new Trade("RELIANCE", 500, 5),
            new Trade("TCS", 300, 10),
            new Trade("INFY", 700, 15),
            new Trade("RELIANCE", 400, 20),
            new Trade("HDFC", 200, 30),
            new Trade("INFY", 100, 45),
            new Trade("TCS", 900, 50),      // still minute 1
            new Trade("RELIANCE", 600, 65), // minute 2 → closes minute 1
            new Trade("WIPRO", 800, 70),
            new Trade("TCS", 150, 80)
        );

        log.info("=== Streaming trades (stateful, per-minute top 5) ===");
        for (int i = 0; i < stream.size(); i++) {
            proc.process(stream.get(i));
            if (i == 3) proc.checkpoint(); // mid-stream checkpoint
        }
        proc.flush(); // close final window
    }
}
